import { Component } from '@angular/core';
import { BookingService } from '../../services/booking.service';
import { Room } from 'src/app/common/room-site/models/room.model';
import { ActivatedRoute } from '@angular/router';
import { RouteUrlRecordService } from 'src/app/auth-route/services/route-url-record.service';
import { GoogleAuthService } from 'src/app/auth-route/services/google-auth.service';
import { GoogleAuthUser } from 'src/app/auth-route/models/google-auth-user.model';
import { DialogItemModel } from 'src/app/common/dialog/models/item.model';
import { Site } from 'src/app/common/room-site/models/site.model';
import { RoomSiteIsBooking } from 'src/app/common/room-site/models/room-site-isbooking.model';

@Component({
  selector: 'app-booking-check-form-page',
  templateUrl: './booking-check-form-page.component.html',
  styleUrls: ['./booking-check-form-page.component.scss']
})
export class BookingCheckFormPageComponent {

  // loading畫面, 等待 教室相關資訊取得
  isLoading = true;

  // booking 種類, 教室預約/座位預約
  bookingType = "";

  // 教室座位, 是否預約列表
  roomSiteIsBookingList: RoomSiteIsBooking[] = [];

  // 教室 list
  roomList = new Array<Room>();
  // 選擇教室
  selectRoom!: Room;
  // 教室 dialog 資訊
  dialogRoomList: DialogItemModel[] = [];
  // 教室dialog 是否隱藏 
  isHiddenDialogRoom = true;

  // 選擇座位
  selectSite!: Site;
  // 座位 dialog 資訊
  dialogSiteList: DialogItemModel[] = [];
  // 座位 dialog是否隱藏 
  isHiddenDialogSite = true;
  // 座位 所有資訊 
  dialogSiteAllList: Site[] =[];

  // 當前使用者資訊
  currentUser!: GoogleAuthUser;
  // 使用者 dialog 資訊
  dialogUserInfo: DialogItemModel[] = [];
  // 使用者 dialog 是否隱藏 
  isHiddenDialogUserInfo = true;

  constructor(
    private routeUrlRecordService: RouteUrlRecordService<{}>,
    private activatedRoute: ActivatedRoute,
    private bookingService: BookingService,
    private googleAuthService: GoogleAuthService,
  ) { }

  ngOnInit(): void {
    // 取得使用者資訊
    this.currentUser = this.googleAuthService.getCurrentUser();
    if(!this.currentUser) {
      alert("無法取得使用者資訊，請重新登入。");
      this.routeUrlRecordService.nextPage("/", {});
    }
    this.dialogUserInfo.push({id: "0", name: "姓名: " + this.currentUser.name});
    this.dialogUserInfo.push({id: "1", name: "信箱: " + this.currentUser.email});


    // 取得 教室,座位 資訊
    this.bookingService
      .getRoomSiteByDate(this.getSelectDate(), this.getStartTime(), this.getEndTime())
      .subscribe(roomSiteList => {
        roomSiteList.forEach((roomSite: RoomSiteIsBooking) => {
          this.roomSiteIsBookingList.push(
            new RoomSiteIsBooking(roomSite)
          );
        });
        this.checkLoading();
      },
      error => {
        alert("教室資訊無法取得,錯誤資訊 2 : " + error);
      });


    // 取得 教室資訊
    const ownerId = this.currentUser.id;
    this.bookingService
      .getRoomByOwnerId(ownerId)
      .subscribe(res => {
        res.forEach(room => {
            this.roomList.push(
              new Room(room)
            );
            this.dialogRoomList.push({id:room['id'], name: room['name'], isDisabled: false});
          });
          this.selectRoom = this.roomList[0];
          this.checkLoading();
        },
        error => {
          alert("教室資訊無法取得,錯誤資訊 3 : " + error);
        }
      );
    
    // 取得 座位資訊
    this.bookingService
        .getAllSiteList()
        .subscribe(dataList => {
          dataList.forEach((site: any) => {
            this.dialogSiteAllList.push(
              new Site(site)
            );
          });
          this.checkLoading();
        });

    // 取得 booking 種類
    this.activatedRoute.queryParams.subscribe(params => {
      this.bookingType = params['bookingType'];
    });
  }

  /* 
   * 檢查 教室座位資訊是否取得完成, 並關閉loading
   */
  checkLoading() { 
    if( this.roomSiteIsBookingList.length > 0 && 
        this.dialogRoomList.length > 0 && 
        this.dialogSiteAllList.length > 0) {
      this.isLoading = false;
    }
  }

  /*
   *  從 service 取得 選擇日期
   */
  getSelectDate() {
    return this.bookingService.getSelectDate();
  }

  /*
   * 從 service 取得 開始時間 
   */
  getStartTime() {
    return this.bookingService.getStartTime();
  }

  /*
   * 從 service 取得 結束時間 
   */
  getEndTime() {
    return this.bookingService.getEndTime();
  }

  /*
   * 教室 dialog 選擇之後觸發 
   */
  selectedRoom(_selectRoomId: string) {
    if(!_selectRoomId) {
      return;
    }
    this.selectRoom = this.roomList.filter(room => {return room.id === _selectRoomId; })[0];
    // 預設選擇一個 座位空間
    this.selectSite = new Site(null);
    //this.selectedSite((this.dialogSiteAllList.filter(site => {return site.roomId === this.selectRoom.id})[0]).id);
  }

  /* 
   * 座位 dialog 選擇觸發
   */
  selectedSite(_selectSiteId: string) {
    if(!_selectSiteId) {
      return;
    }
    this.selectSite = this.dialogSiteAllList.filter(site => {return site.id === _selectSiteId; })[0];
  }

  /*
   * 按下送出 icon , post booking預約資訊 
   */
  submitBooking() {

    if(!this.currentUser) {
      alert("使用者資訊不足，請重新登入");
      return;
    }

    if(this.currentUser.email === "") {
      alert("無法取得使用者 email，請重新登入");
      return;
    }

    if(this.currentUser.id === "") {
      alert("無法取得使用者 id，請重新登入");
      return;
    }

    if(!this.selectRoom) {
      alert("請選擇教室");
      return;
    }

    if(!this.selectSite) {
      alert("請選擇座位");
      return;
    }

    if(!this.selectSite.name) {
      alert("請選擇座位");
      return;
    }

    this.isLoading = true;


    // 重新 檢查 座位是否重複
    this.bookingService
      .getRoomSiteByDate(this.getSelectDate(), this.getStartTime(), this.getEndTime())
      .subscribe(roomSiteList => {
        const isBooking = roomSiteList.filter((record) => {
          return record.id === this.selectSite.id && record.isBooking
        });
        if(isBooking.length > 0 && this.bookingType === "site") {
          alert("晚了一步, 該座位剛剛已被其他人預約了喔！");
          this.isLoading = false;
        }
        else {
          const bookingData = { 
            //id: "",
            id: "",
            userId: this.currentUser.id, 
            mail: this.currentUser.email, 
            startDate: this.getSelectDate(), 
            endDate: this.getSelectDate(), 
            startTime: this.getStartTime(),
            endTime: this.getEndTime(),
            bookingType: this.bookingType,
            roomId: this.selectRoom.id,
            roomName: this.selectRoom.name,
            siteId: this.selectSite.id,
            siteName: this.selectSite.name,
          };
      
          this.bookingService.post(bookingData)      
            .subscribe(() => {
              alert("送出成功, 預約時間: " 
                      + this.getSelectDate() + " " + this.getStartTime() + "~" + this.getEndTime() 
                      + " ,地點:" + this.selectRoom.name + " " + this.selectSite.name + " 預約成功。");
              this.routeUrlRecordService.nextPage("/home", {});
            },
            error => {
              alert("資料送出失敗,請重新輸入, 錯誤訊息 " + JSON.stringify(error));
            });
          alert("資料傳輸中");
        }
      },
      error => {
        alert("教室資訊無法取得,錯誤資訊 1 : " + error);
      });
  }

  /*
   * 點選 座位 dialog 
   */
  clickSiteShowDialog() {
    this.isHiddenDialogSite=false;
    this.dialogSiteList = [];
    this.roomSiteIsBookingList.forEach(roomSite => {
      if(roomSite.roomId === this.selectRoom.id) {
        this.dialogSiteList.push({id:roomSite.id , name: roomSite.siteName, isDisabled:roomSite.isBooking});
      }
    });
  }

  selectMap() {
    //this.router.navigate(["map"]);
  }
}
